{total}] {elapsed:.0f}s elapsed, ETA {eta:.0f}s | {dgp_name} k={k} {regime_name} ne={ne} sigma={sigma} mc={mc}\")\n\n    return pd.DataFrame(results), time.time() - t0\n\n\nif __name__ == '__main__':\n    dry_run = '--dry-run' in sys.argv\n    args = [a for a in sys.argv[1:] if a != '--dry-run']\n    n_mc = int(args[0]) if args else N_MC\n\n    if dry_run:\n        n_mc = 1\n        sigma_list = [0.5]\n        k_list = [2]\n        dgp_list = list(DGP_CONFIGS.keys())\n    else:\n        sigma_list = None\n        k_list = [2, 4]\n        dgp_list = None\n\n    methods_str = 'oracle, naive, global_corrected, stratified_mle, ec_hte, mi_rubin, ppci, ec_hte_ppci'\n    print(f\"exp-007: PPCI + EC-HTE 4-DGP Matrix\")\n    print(f\"N={N}, N_MC={n_mc}\")\n    print(f\"Methods: {methods_str}\")\n    print(f\"DGPs: {dgp_list if dgp_list else list(DGP_CONFIGS.keys())}\")\n    print(f\"Outcome noise levels: {sigma_list if sigma_list else OUTCOME_NOISE_LEVELS}\")\n    print(f\"HB: Gibbs sampler (4 chains, 4000 iter, 2000 warmup, Dirichlet-Multinomial)\")\n    if dry_run:\n        print(f\"** DRY RUN: 1 MC, k=[2], sigma=[0.5], all 4 DGPs **\")\n    print()\n\n    df_raw, elapsed = run_simulation(n_mc, k_list=k_list, sigma_list=sigma_list,\n                                     dgp_list=dgp_list)\n    df_agg = aggregate_results(df_raw)\n\n    raw_path = 'results/exp007_ppci_dsl_hb_raw.csv'\n    agg_path = 'results/exp007_ppci_dsl_hb.csv'\n    df_raw.to_csv(raw_path, index=False)\n    df_agg.to_csv(agg_path, index=False)\n\n    print(f\"\\nTotal time: {elapsed:.1f}s\")\n    print(f\"Saved: {raw_path}, {agg_path}\")\n\n    pd.set_option('display.max_columns', 20)\n    pd.set_option('display.width', 240)\n    pd.set_option('display.float_format', '{:.4f}'.format)\n\n    for dgp in (dgp_list or list(DGP_CONFIGS.keys())):\n        for regime in REGIMES:\n            print(f\"\\n{'='*140}\")\n            print(f\"DGP: {dgp} | Regime: {regime}\")\n            print(f\"{'='*140}\")\n            sub = df_agg[(df_agg['regime'] == regime) & (df_agg['dgp'] == dgp)]\n            if sub.empty:\n                continue\n            cols = ['n_expert', 'k_subgroups', 'sigma_outcome', 'subgroup', 'method',\n                    'bias_z0', 'rmse_z0', 'coverage_z0', 'bias_z1', 'rmse_z1', 'coverage_z1']\n            print(sub[cols].to_string(index=False))\n","structuredPatch":[{"oldStart":8,"oldLines":6,"newStart":8,"newLines":10,"lines":["   Rectifier was using Z_hat grouping on gold subset, capturing both covariate and outcome error.","   Since M^{-1} already corrects covariate error, this caused double correction under DGP A/C.","   Fixed: rectifier now uses true Z grouping on gold subset so it only captures outcome error.","+","+HB backfill (2026-05-21): replaced MLE placeholder in ec_hte/ec_hte_ppci with real HB Gibbs","+  sampler (Dirichlet-Multinomial, 4 chains, 4000 iter, 2000 warmup). Ported from exp-003.","+  Added invert_mixing_safe with cond(M) > 100 singularity guard."," \"\"\""," "," import numpy as np"]}],"userModified":false,"replaceAll":false}}
